<?php
declare(strict_types=1);require dirname(__DIR__).'/app/bootstrap.php';Auth::requireLogin();
$cats=$db->query('SELECT id,name FROM age_categories ORDER BY sort_order,name')->fetchAll();$teams=$db->query('SELECT id,name,category_id,badge_path,coach_name,active FROM teams ORDER BY name')->fetchAll();
$edit=null;if(isset($_GET['edit'])){$st=$db->prepare('SELECT * FROM competitions WHERE id=?');$st->execute([(int)$_GET['edit']]);$edit=$st->fetch()?:null;}
$teamEdit=null;if(isset($_GET['team'])){$st=$db->prepare('SELECT * FROM teams WHERE id=?');$st->execute([(int)$_GET['team']]);$teamEdit=$st->fetch()?:null;}
$achievementEdit=null;if(isset($_GET['achievement'])){$st=$db->prepare('SELECT * FROM achievements WHERE id=?');$st->execute([(int)$_GET['achievement']]);$achievementEdit=$st->fetch()?:null;}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$action=$_POST['action']??'save_comp';
if($action==='delete_comp'){$db->prepare('DELETE FROM competitions WHERE id=?')->execute([(int)$_POST['id']]);flash('success','Competição excluída.');}
elseif($action==='save_team'){$id=(int)($_POST['id']??0);$badge=upload_image('badge_path',($_POST['current_badge']??'')?:null);$data=[trim($_POST['name']),nullable_int($_POST['category_id']),trim($_POST['coach_name']),$badge,trim($_POST['notes']),isset($_POST['active'])?1:0];if($id){$data[]=$id;$db->prepare('UPDATE teams SET name=?,category_id=?,coach_name=?,badge_path=?,notes=?,active=? WHERE id=?')->execute($data);}else{$db->prepare('INSERT INTO teams(name,category_id,coach_name,badge_path,notes,active) VALUES(?,?,?,?,?,?)')->execute($data);}flash('success','Time salvo.');}
elseif($action==='delete_team'){$db->prepare('DELETE FROM teams WHERE id=?')->execute([(int)$_POST['id']]);flash('success','Time excluído.');}
elseif($action==='save_achievement'){$id=(int)($_POST['id']??0);$img=upload_image('image_path',($_POST['current_image']??'')?:null);$data=[trim($_POST['title']),nullable_int($_POST['category_id']),nullable_int($_POST['achievement_year']),trim($_POST['placement']),trim($_POST['description']),$img,1];if($id){$data[]=$id;$db->prepare("UPDATE achievements SET title=?,category_id=?,achievement_year=?,placement=?,description=?,image_path=?,active=? WHERE id=?")->execute($data);}else{$db->prepare("INSERT INTO achievements(title,category_id,achievement_year,placement,description,image_path,source_type,active) VALUES(?,?,?,?,?,?,'manual',?)")->execute($data);}flash('success','Conquista salva.');}
elseif($action==='delete_achievement'){$db->prepare("DELETE FROM achievements WHERE id=? AND source_type='manual'")->execute([(int)$_POST['id']]);flash('success','Conquista manual excluída.');}
elseif($action==='sync_achievements'){$db->exec("INSERT INTO achievements(competition_id,title,category_id,achievement_year,placement,description,image_path,source_type,active) SELECT id,name,category_id,YEAR(COALESCE(end_date,start_date,CURDATE())),placement,description,trophy_image,'automatico',1 FROM competitions WHERE is_achievement=1 ON DUPLICATE KEY UPDATE title=VALUES(title),category_id=VALUES(category_id),achievement_year=VALUES(achievement_year),placement=VALUES(placement),description=VALUES(description),image_path=VALUES(image_path),active=1");flash('success','Conquistas sincronizadas.');}
else{$id=(int)($_POST['id']??0);$img=upload_image('trophy_image',($_POST['current_image']??'')?:null);$data=[trim($_POST['name']),nullable_int($_POST['category_id']),$_POST['competition_type'],trim($_POST['format_name']),$_POST['status'],$_POST['start_date']?:null,$_POST['end_date']?:null,trim($_POST['location']),trim($_POST['description']),trim($_POST['participant_notes']),isset($_POST['is_achievement'])?1:0,trim($_POST['placement']),$img];if($id){$data[]=$id;$db->prepare('UPDATE competitions SET name=?,category_id=?,competition_type=?,format_name=?,status=?,start_date=?,end_date=?,location=?,description=?,participant_notes=?,is_achievement=?,placement=?,trophy_image=? WHERE id=?')->execute($data);}else{$db->prepare('INSERT INTO competitions(name,category_id,competition_type,format_name,status,start_date,end_date,location,description,participant_notes,is_achievement,placement,trophy_image) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute($data);$id=(int)$db->lastInsertId();}$db->prepare('DELETE FROM competition_teams WHERE competition_id=?')->execute([$id]);foreach((array)($_POST['team_ids']??[]) as $tid)$db->prepare('INSERT IGNORE INTO competition_teams(competition_id,team_id) VALUES(?,?)')->execute([$id,(int)$tid]);if(isset($_POST['is_achievement']))$db->prepare("INSERT INTO achievements(competition_id,title,category_id,achievement_year,placement,description,image_path,source_type,active) VALUES(?,?,?,?,?,?,?,'automatico',1) ON DUPLICATE KEY UPDATE title=VALUES(title),category_id=VALUES(category_id),achievement_year=VALUES(achievement_year),placement=VALUES(placement),description=VALUES(description),image_path=VALUES(image_path),active=1")->execute([$id,trim($_POST['name']),nullable_int($_POST['category_id']),date('Y',strtotime($_POST['end_date']?:($_POST['start_date']?:'now'))),trim($_POST['placement']),trim($_POST['description']),$img]);flash('success','Competição salva.');}
}catch(Throwable $e){flash('danger',$e->getMessage());}redirect('competitions.php');}
$rows=$db->query('SELECT c.*,a.name category_name,(SELECT COUNT(*) FROM competition_teams ct WHERE ct.competition_id=c.id) team_count FROM competitions c LEFT JOIN age_categories a ON a.id=c.category_id ORDER BY c.start_date DESC,c.id DESC')->fetchAll();$achievements=$db->query('SELECT a.*,c.name category_name FROM achievements a LEFT JOIN age_categories c ON c.id=a.category_id ORDER BY achievement_year DESC,a.id DESC')->fetchAll();$selected=[];if($edit){$st=$db->prepare('SELECT team_id FROM competition_teams WHERE competition_id=?');$st->execute([$edit['id']]);$selected=array_map('intval',array_column($st->fetchAll(),'team_id'));}require __DIR__.'/_header.php';?>
<div class="page-title"><div><h1>Competições, times e conquistas</h1><p>Gerencie todo o ambiente competitivo em uma única página.</p></div><a class="btn" href="matches.php">Partidas e súmulas</a></div>
<div class="admin-tabs"><a href="#competicoes">Competições</a><a href="#times">Times inscritos</a><a href="#conquistas">Conquistas</a></div>
<section id="competicoes"><div class="admin-grid"><form method="post" enctype="multipart/form-data" class="panel form-stack"><?=csrf_field()?><input type="hidden" name="action" value="save_comp"><input type="hidden" name="id" value="<?=e((string)($edit['id']??''))?>"><input type="hidden" name="current_image" value="<?=e($edit['trophy_image']??'')?>"><h2><?=$edit?'Editar':'Nova'?> competição</h2><label>Nome<input name="name" value="<?=e($edit['name']??'')?>" required></label><label>Categoria<select name="category_id"><option value="">Todas</option><?php foreach($cats as $c):?><option value="<?=$c['id']?>" <?=($edit['category_id']??null)==$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select></label><label>Tipo<select name="competition_type"><?php foreach(['campeonato','torneio','amistoso'] as $v):?><option value="<?=$v?>" <?=($edit['competition_type']??'torneio')===$v?'selected':''?>><?=ucfirst($v)?></option><?php endforeach;?></select></label><label>Formato<select name="format_name"><?php foreach(['Pontos corridos','Mata-mata','Grupos + mata-mata','Quadrangular','Hexagonal','Festival','Personalizado'] as $v):?><option <?=($edit['format_name']??'')===$v?'selected':''?>><?=$v?></option><?php endforeach;?></select></label><label>Status<select name="status"><?php foreach(['proximo','andamento','concluido'] as $v):?><option value="<?=$v?>" <?=($edit['status']??'proximo')===$v?'selected':''?>><?=ucfirst($v)?></option><?php endforeach;?></select></label><div class="inline-fields"><label>Início<input type="date" name="start_date" value="<?=e($edit['start_date']??'')?>"></label><label>Fim<input type="date" name="end_date" value="<?=e($edit['end_date']??'')?>"></label></div><label>Local<input name="location" value="<?=e($edit['location']??'')?>"></label><label>Times inscritos<select name="team_ids[]" multiple size="7"><?php foreach($teams as $t):?><option value="<?=$t['id']?>" <?=in_array((int)$t['id'],$selected,true)?'selected':''?>><?=e($t['name'])?></option><?php endforeach;?></select></label><label>Participantes / observações<textarea name="participant_notes" rows="3"><?=e($edit['participant_notes']??'')?></textarea></label><label>Descrição<textarea name="description" rows="3"><?=e($edit['description']??'')?></textarea></label><label class="check"><input type="checkbox" name="is_achievement" <?=($edit['is_achievement']??0)?'checked':''?>> Gerar conquista automaticamente</label><label>Colocação<input name="placement" value="<?=e($edit['placement']??'')?>" placeholder="Campeão, vice-campeão..."></label><label>Imagem/troféu<input type="file" name="trophy_image" accept="image/*"></label><button class="btn primary">Salvar competição</button></form><div class="panel"><div class="table-wrap"><table><thead><tr><th>Competição</th><th>Categoria</th><th>Formato</th><th>Times</th><th>Status</th><th>Ações</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['name'])?><?=$r['is_achievement']?' 🏆':''?></td><td><?=e($r['category_name']??'Todas')?></td><td><?=e($r['format_name']??'—')?></td><td><?=(int)$r['team_count']?></td><td><?=e($r['status'])?></td><td class="actions"><a href="?edit=<?=$r['id']?>#competicoes">Editar</a><form method="post" onsubmit="return confirm('Excluir competição?')"><?=csrf_field()?><input type="hidden" name="action" value="delete_comp"><input type="hidden" name="id" value="<?=$r['id']?>"><button>Excluir</button></form></td></tr><?php endforeach;?></tbody></table></div></div></div></section>
<section id="times" class="section-admin"><div class="admin-grid"><form method="post" enctype="multipart/form-data" class="panel form-stack"><?=csrf_field()?><input type="hidden" name="action" value="save_team"><input type="hidden" name="id" value="<?=e((string)($teamEdit['id']??''))?>"><input type="hidden" name="current_badge" value="<?=e($teamEdit['badge_path']??'')?>"><h2><?=$teamEdit?'Editar':'Novo'?> time</h2><label>Nome<input name="name" value="<?=e($teamEdit['name']??'')?>" required></label><label>Categoria<select name="category_id"><option value="">Sem categoria</option><?php foreach($cats as $c):?><option value="<?=$c['id']?>" <?=($teamEdit['category_id']??null)==$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select></label><label>Técnico<input name="coach_name" value="<?=e($teamEdit['coach_name']??'')?>"></label><label>Logo<input type="file" name="badge_path" accept="image/*"></label><?php if(!empty($teamEdit['badge_path'])):?><img class="preview-logo" src="../<?=e($teamEdit['badge_path'])?>"><?php endif;?><label>Observações<textarea name="notes" rows="3"><?=e($teamEdit['notes']??'')?></textarea></label><label class="check"><input type="checkbox" name="active" <?=!isset($teamEdit['active'])||$teamEdit['active']?'checked':''?>> Ativo</label><button class="btn primary">Salvar time</button></form><div class="panel"><div class="table-wrap"><table><thead><tr><th>Logo</th><th>Time</th><th>Técnico</th><th>Ações</th></tr></thead><tbody><?php foreach($teams as $t):?><tr><td><?php if($t['badge_path']):?><img class="mini-team-logo" src="../<?=e($t['badge_path'])?>"><?php else:?>—<?php endif;?></td><td><?=e($t['name'])?></td><td><?=e($t['coach_name']??'—')?></td><td class="actions"><a href="?team=<?=$t['id']?>#times">Editar</a><form method="post" onsubmit="return confirm('Excluir time?')"><?=csrf_field()?><input type="hidden" name="action" value="delete_team"><input type="hidden" name="id" value="<?=$t['id']?>"><button>Excluir</button></form></td></tr><?php endforeach;?></tbody></table></div></div></div></section>
<section id="conquistas" class="section-admin"><div class="panel-head"><div><h2>Galeria de títulos e conquistas</h2><p>Cadastros manuais e registros automáticos vindos das competições.</p></div><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="sync_achievements"><button class="btn">Sincronizar conquistas</button></form></div><div class="admin-grid"><form method="post" enctype="multipart/form-data" class="panel form-stack"><?=csrf_field()?><input type="hidden" name="action" value="save_achievement"><input type="hidden" name="id" value="<?=e((string)($achievementEdit['id']??''))?>"><input type="hidden" name="current_image" value="<?=e($achievementEdit['image_path']??'')?>"><h2><?=$achievementEdit?'Editar':'Nova'?> conquista manual</h2><label>Título<input name="title" value="<?=e($achievementEdit['title']??'')?>" required></label><label>Categoria<select name="category_id"><option value="">Todas</option><?php foreach($cats as $c):?><option value="<?=$c['id']?>" <?=($achievementEdit['category_id']??null)==$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select></label><label>Ano<input type="number" name="achievement_year" min="1900" max="2100" value="<?=e((string)($achievementEdit['achievement_year']??date('Y')))?>"></label><label>Colocação<input name="placement" value="<?=e($achievementEdit['placement']??'')?>"></label><label>Descrição<textarea name="description" rows="3"><?=e($achievementEdit['description']??'')?></textarea></label><label>Imagem<input type="file" name="image_path" accept="image/*"></label><button class="btn primary">Salvar conquista</button></form><div class="panel"><div class="achievement-admin-grid"><?php foreach($achievements as $a):?><article><?php if($a['image_path']):?><img src="../<?=e($a['image_path'])?>"><?php else:?><span class="trophy-placeholder">🏆</span><?php endif;?><div><small><?=e($a['source_type']==='automatico'?'Automático':'Manual')?> • <?=e((string)$a['achievement_year'])?></small><h3><?=e($a['title'])?></h3><p><?=e(trim(($a['placement']?:'').($a['category_name']?' • '.$a['category_name']:'')))?></p></div><div class="actions"><?php if($a['source_type']==='manual'):?><a href="?achievement=<?=$a['id']?>#conquistas">Editar</a><form method="post" onsubmit="return confirm('Excluir conquista?')"><?=csrf_field()?><input type="hidden" name="action" value="delete_achievement"><input type="hidden" name="id" value="<?=$a['id']?>"><button>Excluir</button></form><?php endif;?></div></article><?php endforeach;?></div></div></div></section><?php require __DIR__.'/_footer.php';?>
